import type {LessonGuide,ChecklistGuide} from './lesson-types';

type Ref = [title:string,url:string,focus:string,read:string,action:string];
type Review = {intro:[string,string];steps:[string,string][];refs:Ref[];task:string;input:string;expected:string;hint:string;pitfall:string};
const git:Ref=['Pro Git: First-Time Git Setup','https://git-scm.com/book/en/v2/Getting-Started-First-Time-Git-Setup','پیکربندی هویت؛ سپس Git Basics در فهرست همین کتاب','نام و ایمیل commit را بشناس؛ در Git Basics فقط ساخت مخزن، stage، commit و log را دنبال کن.','روی پوشه تمرین git status اجرا کن و تفاوت فایل تغییرکرده، stage‌شده و commit‌شده را با یک تغییر ببین.'];
const goTest:Ref=['Go Tutorials','https://go.dev/doc/tutorial/','Create a Go module و Add a test','آموزش ساخت ماژول و افزودن تست را از فهرست انتخاب کن؛ assertion رفتار تابع و اجرای go test را دنبال کن.','برای رفتار همین تمرین یک تست بنویس که با حذف اصلاح تو شکست بخورد.'];
const gin:Ref=['Go RESTful API Tutorial','https://go.dev/doc/tutorial/web-service-gin','Design API endpoints، Write a handler و Add data','به ارتباط مسیر، handler، JSON و status در آموزش توجه کن؛ این آموزش به‌تنهایی کنترل مالکیت را پیاده نمی‌کند.','جدول مسیرها و نمونه body تمرین خودت را کنار قرارداد نمونه بنویس.'];
const sql:Ref=['PostgreSQL Tutorial','https://www.postgresql.org/docs/current/tutorial.html','Joins Between Tables و Transactions','از فهرست، بخش Join و Transaction را انتخاب کن؛ BEGIN، COMMIT و ROLLBACK را با داده آزمایشی اجرا کن.','یک نتیجه Join و یک وضعیت قبل و بعد rollback ذخیره کن.'];
const docker:Ref=['Docker Get Started','https://docs.docker.com/get-started/','Containerize your application و Docker Compose','مفهوم image/container و تعریف چند سرویس را بخوان؛ وابستگی‌ها و volume برنامه خودت را مشخص کن.','اجرای API و DB را با فرمان‌های مستند از clone تازه تکرار کن؛ volume داده واقعی را حذف نکن.'];
const react:Ref=['React Learn','https://react.dev/learn','Describing the UI، Adding Interactivity و Managing State','فهرست و فرم و state را دنبال کن؛ مالک state و جریان props را روی پنل خودت پیدا کن.','ورودی فرم، پیام خطا و فهرست Task را به Componentهای واقعی مخزن وصل کن.'];
const ts:Ref=['TypeScript Handbook','https://www.typescriptlang.org/docs/handbook/intro.html','Everyday Types و Narrowing','Union، Object type و narrowing را از فهرست Handbook بخوان؛ تفاوت نوع ایستا با داده JSON ناشناس را حفظ کن.','یک خطای نوع عمدی و یک JSON نامعتبر که از شبکه آمده را جدا آزمایش کن.'];
const torch:Ref=['PyTorch Learn the Basics','https://docs.pytorch.org/tutorials/beginner/basics/intro.html','Optimization و Save and Load the Model','حلقه آموزش و ارزیابی و ذخیره state_dict را بخوان؛ اجرای eval و no_grad در ارزیابی را بررسی کن.','checkpoint خودت را در فرایند تازه بارگذاری کن و یک batch را دوباره پیش‌بینی کن.'];
const hf:Ref=['Hugging Face Fine-tuning','https://huggingface.co/docs/transformers/main/training','Prepare a dataset، Train و Evaluate','بخش آماده‌سازی داده و ارزیابی را با نسخه نصب‌شده Transformers تطبیق بده؛ کل راهنما قرار نیست در این جلسه تمام شود.','تنظیمات، مدل پایه و روش ارزیابی آزمایش خودت را در یک فایل ثابت ثبت کن.'];
const issue:Ref=['GitHub Docs: Creating an issue','https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/creating-an-issue','Creating an issue from a repository','روش ثبت issue و نوشتن عنوان و شرح را بخوان؛ issue باید یک رفتار قابل بررسی داشته باشد.','برای یک کار کوچک ورودی، رفتار مطلوب، وابستگی و معیار پذیرش بنویس.'];
const api:Ref=['OpenAPI Specification','https://spec.openapis.org/oas/latest.html','Paths، Operation، Parameters، Request Body و Responses','برای قرارداد کوچک فقط ساختار مسیر، ورودی و پاسخ را از فهرست دنبال کن؛ لازم نیست تمام specification را بخوانی.','یک endpoint واقعی خودت را با Method، body، status و خطاهایش مستند کن.'];

const reviews:Review[]=[
 {intro:['Git تاریخچه تغییرات کد را نگه می‌دارد. پوشه کاری، stage و commit سه وضعیت متفاوت‌اند: ذخیره فایل در ویرایشگر هنوز آن را وارد تاریخچه نمی‌کند.','در این جلسه سه برنامه Go را به یک خروجی قابل اجرا تبدیل می‌کنی. README باید به فردی که کد را ندیده بگوید چه برنامه‌ای را با چه ورودی اجرا کند و چه خروجی ببیند.'],steps:[['پوشه‌ها را جدا کن','برای calculator، parity و fizzbuzz پوشه جدا بگذار تا چند تابع main با هم تداخل نکنند. هر برنامه را از ترمینال اجرا و فرمانش را یادداشت کن.'],['اولین تغییر را ثبت کن','داخل پوشه تمرین git init اجرا کن، هویت محلی خودت را تنظیم کن و با git status فایل‌ها را ببین. فایل‌های کد و README را stage و commit کن؛ فایل secret اضافه نکن.'],['README قابل تکرار بنویس','برای هر برنامه یک ورودی معتبر، یک ورودی نامعتبر، فرمان اجرا و خروجی واقعی ثبت کن. سپس یک حلقه را بدون نگاه به درس بازنویسی کن و تفاوت‌ها را توضیح بده.']],refs:[git,goTest],task:'برای برنامه زوج/فرد یک بخش README و یک commit مستقل بساز.',input:'عدد ۸، عدد ۷ و رشته hello را به برنامه بده.',expected:'۸ زوج و ۷ فرد گزارش شود؛ hello پیام خطای روشن بگیرد و اجرای بعدی برنامه ممکن باشد.',hint:'خروجی را پیش از اجرا روی کاغذ پیش‌بینی کن؛ سپس با اجرای واقعی مقایسه کن.',pitfall:'git add . بدون دیدن git status ممکن است فایل‌های اضافی یا اطلاعات محیط را وارد تاریخچه کند.'},
 {intro:['بازسازی از حافظه نشان می‌دهد ساختار حل مسئله را فهمیده‌ای یا فقط شکل کد را به یاد داری. اگر یک تابع را نمی‌توانی دوباره بنویسی، ورودی و خروجی آن را کوچک‌تر تعریف کن.','بازبینی AI یک پیشنهاد است. تغییر پیشنهادی را تنها وقتی بپذیر که بتوانی مثال شکست نسخه فعلی و علت درست‌بودن نسخه تازه را توضیح بدهی.'],steps:[['قرارداد را بنویس','برای countDone ورودی []Task و خروجی عدد صحیح تعریف کن. رفتار Slice خالی، یک Task انجام‌شده و چند وضعیت مختلف را پیش از کدنویسی مشخص کن.'],['بدون منبع پیاده کن','فایل جدیدی باز کن و تابع را بدون بازکردن مثال قبلی بنویس. پس از اجرا، نسخه قبلی را برای مقایسه نگاه کن؛ نقطه‌ای را که گیر کردی ثبت کن.'],['پیشنهاد را آزمایش کن','از AI فقط بازبینی همین تابع را بخواه. یکی از پیشنهادها را با داده معلوم امتحان کن؛ اگر تغییری لازم نبود دلیل رد پیشنهاد را بنویس.']],refs:[goTest],task:'شمارش Taskهای انجام‌شده را بازسازی و یک اصلاح با دلیل ثبت کن.',input:'سه Task با وضعیت‌های done، todo و done؛ سپس Slice خالی.',expected:'نتیجه‌ها به‌ترتیب ۲ و ۰ باشند؛ هیچ داده‌ای حین شمارش تغییر نکند.',hint:'این تابع فقط خواندن داده است؛ تغییر وضعیت Task در شمارش، مسئولیت اضافه و منشأ bug است.',pitfall:'اجرای موفق برای یک ورودی، دلیل درست‌بودن تغییر AI برای همه حالت‌ها نیست.'},
 {intro:['قرارداد Store مشخص می‌کند add، update یا delete چه ورودی می‌گیرند و چه خطایی برمی‌گردانند. پیام خطا باید علت شکست را به caller بدهد تا رفتار درست انتخاب کند.','گزارش bug قابل استفاده چهار بخش دارد: ورودی، رفتار مشاهده‌شده، رفتار مطلوب و حداقل کدی که مشکل را تکرار می‌کند. اصلاح بدون بازتولید ممکن است علت واقعی را پنهان کند.'],steps:[['قرارداد خطا را روشن کن','برای delete شناسه موجود و ناموجود تعریف کن. تصمیم بگیر حذف ناموجود error برگرداند یا idempotent باشد و همین تصمیم را در قرارداد ثبت کن.'],['مثال شکست را کوچک کن','Store خالی بساز و delete برای id=99 بزن. اگر panic یا حذف اشتباه رخ داد، تنها داده لازم برای بازتولید را در تست نگه دار.'],['اصلاح و اثبات کن','خطا را در محل مسئول برگردان، caller را مجبور به بررسی آن کن و همان تست را دوباره اجرا کن. commit باید تست و اصلاح را با هم داشته باشد.']],refs:[goTest],task:'رفتار delete روی Task ناموجود را مستند و تست کن.',input:'Store شامل Task با id=1؛ درخواست حذف id=99.',expected:'Task ۱ باقی بماند؛ پاسخ خطا مطابق قرارداد باشد و برنامه panic نکند.',hint:'قبل و بعد عملیات، تعداد و شناسه رکوردهای Store را هم مقایسه کن.',pitfall:'گرفتن panic در بیرونی‌ترین لایه، جای اصلاح دسترسی اشتباه به داده را نمی‌گیرد.'},
 {intro:['تحویل ماه اول یعنی برنامه بیرون از نشست فعلی تو هم اجرا شود. مسیرهای مطلق سیستم خودت، فایل‌های فراموش‌شده و وابستگی‌های نامشخص معمولاً در clone تازه آشکار می‌شوند.','CLI و اسکریپت Python دو برنامه جدا هستند. README باید محیط و فرمان هرکدام را جدا توضیح بدهد و داده نمونه غیرشخصی همراه پروژه باشد.'],steps:[['فهرست تحویل بساز','سه برنامه کوچک Go، مدیر Task با JSON و اسکریپت Python را با مسیر فایل و فرمان اجرای هرکدام فهرست کن. خروجی ساخته‌نشده را از فهرست تحویل کامل حذف کن.'],['محیط تازه آزمایش کن','مخزن را در پوشه تازه clone کن؛ برای Go وابستگی‌ها را طبق go.mod و برای Python محیط مجزا بساز. تنها دستورهای README را دنبال کن.'],['پایداری و خطا را ببین','Task اضافه کن، برنامه را ببند و دوباره list بزن. با کپی داده نمونه، نبود فایل و JSON خراب را بررسی کن؛ فایل اصلی را برای آزمایش خراب نکن.']],refs:[goTest],task:'راهنمای اجرا را با clone تازه راستی‌آزمایی کن.',input:'یک فایل JSON شامل دو Task و یک نسخه کپی با JSON ناقص.',expected:'نسخه سالم گزارش درست بدهد؛ نسخه خراب خطای روشن بگیرد و بی‌صدا بازنویسی نشود.',hint:'هر فرمان فراموش‌شده‌ای که مجبور شدی از حافظه اجرا کنی باید به README اضافه شود.',pitfall:'وجود فایل روی سیستم سازنده، به معنی وجود آن در مخزن نیست؛ git status و فایل‌های track‌شده را بررسی کن.'},
 {intro:['مجموعه درخواست API یک دفترچه آزمایش قابل تکرار است. Method، URL، header، body و انتظار پاسخ باید ذخیره شوند تا هر بار دستی از نو ساخته نشوند.','مخزن Backend به داده نمونه و تنظیمات نمونه نیاز دارد؛ token واقعی و رمز عبور داده آموزشی نیستند. برای اشتراک مجموعه درخواست از متغیر محیطی ابزار استفاده کن.'],steps:[['محیط درخواست تعریف کن','در Bruno یا Postman متغیر baseURL برای سرویس محلی بساز. درخواست GET /health و GET /tasks را با نام روشن ذخیره کن.'],['پاسخ‌ها را ثبت کن','برای مسیر سالم و مسیر ناموجود status، Content-Type و body واقعی را بنویس. فقط عکس موفقیت نگه ندار؛ فایل collection باید در مخزن باشد.'],['از نو تکرار کن','سرویس را متوقف و دوباره اجرا کن؛ مجموعه را از فایل import کن و هر دو درخواست را بفرست. آدرس دستگاه خودت را از فایل عمومی پاک کن.']],refs:[gin,git],task:'یک collection کوچک از سلامت، فهرست و مسیر ناموجود تحویل بده.',input:'GET /health، GET /tasks، GET /does-not-exist روی سرویس محلی.',expected:'دو درخواست اول مطابق قرارداد پاسخ دهند؛ مسیر ناموجود 404 بدهد و متن پاسخ معتبر باشد.',hint:'نام محیط را local بگذار و baseURL را از مقدارهای خصوصی تیم جدا کن.',pitfall:'ذخیره توکن در فایل collection عمومی می‌تواند دسترسی حساب را افشا کند.'},
 {intro:['قرارداد API توافق Client و Server درباره رفتار هر مسیر است. نام مسیر به‌تنهایی کافی نیست؛ ورودی، statusهای ممکن و شکل پاسخ خطا هم جزو قراردادند.','در این هفته لازم نیست specification کامل بنویسی. جدول سه endpoint همراه مثال درخواست و پاسخ واقعی، از سند مفصل ناسازگار با برنامه مفیدتر است.'],steps:[['جدول قرارداد تهیه کن','برای GET /tasks، POST /tasks و GET /tasks/:id، body، path parameter و پاسخ موفق را بنویس. تفاوت ایجاد 201 با خواندن 200 را روشن کن.'],['خطاها را اضافه کن','عنوان خالی یا JSON خراب را برای POST و شناسه ناموجود را برای GET مستند کن. پاسخ خطا باید شکل ثابت و status مناسب داشته باشد.'],['یک handler را بازسازی کن','بدون AI مسیر GET یک Task را دوباره بنویس و با مجموعه درخواست تست کن. سند و رفتار کد را موردبه‌مورد مقایسه کن.']],refs:[gin,api],task:'جدول قرارداد سه مسیر و یک handler مستقل تحویل بده.',input:'POST عنوان خالی؛ GET شناسه 999 که وجود ندارد؛ POST عنوان Read Go.',expected:'دو ورودی نامعتبر خطای مستند بگیرند؛ ورودی سالم Task تازه با شناسه برگرداند.',hint:'شکل JSON خطا را یک‌بار تعیین کن و در تمام مثال‌ها همان را استفاده کن.',pitfall:'سند API که status یا نام فیلد متفاوت از کد دارد، مصرف‌کننده را به مسیر اشتباه می‌برد.'},
 {intro:['Join رکوردهای مرتبط را با کلیدها کنار هم قرار می‌دهد؛ Transaction چند تغییر را یک واحد می‌کند. اگر یکی از تغییرهای وابسته شکست خورد، rollback مانع باقی‌ماندن وضعیت نیمه‌تمام می‌شود.','آزمایش بازیابی باید روی دیتابیس تمرینی باشد. هدف این جلسه اثبات rollback و قابل بازسازی بودن schema است، نه دستکاری یا حذف داده واقعی.'],steps:[['دیتابیس آزمایشی آماده کن','مراحل ایجاد DB و migration را در README بنویس. دو کاربر و سه Task با owner_id معتبر seed کن.'],['رابطه را مشاهده کن','با JOIN نام مالک و عنوان Task را بخوان؛ برای یک کاربر بدون Task بررسی کن INNER JOIN و LEFT JOIN چه تفاوتی نشان می‌دهند.'],['Rollback را اثبات کن','در BEGIN یک Task بساز و تغییر دوم نامعتبر ایجاد کن؛ ROLLBACK بزن و بررسی کن Task نخست این transaction هم ثبت نشده است.']],refs:[sql],task:'گزارش Join و rollback با داده ساختگی تهیه کن.',input:'کاربر A با دو Task، کاربر B بدون Task؛ transaction با INSERT سالم و سپس خطای foreign key.',expected:'LEFT JOIN کاربر B را هم نشان دهد؛ پس از rollback تعداد Taskها با حالت شروع برابر بماند.',hint:'پیش از BEGIN و پس از ROLLBACK یک SELECT COUNT با همان شرط اجرا کن.',pitfall:'COMMIT تصادفی پیش از مرحله خراب، آزمون rollback را بی‌معنی می‌کند.'},
 {intro:['احراز هویت می‌گوید درخواست از چه کاربری است؛ مجوز می‌گوید آن کاربر می‌تواند با این Task چه کند. داشتن JWT معتبر به‌تنهایی اجازه دسترسی به همه Taskها نمی‌دهد.','آزمون دو کاربر باید هم خواندن و هم تغییر را بسنجد. پنهان‌کردن یک دکمه در UI یا فیلتر فهرست، جلوی درخواست مستقیم با شناسه کاربر دیگر را نمی‌گیرد.'],steps:[['دو هویت جدا بساز','کاربران A و B را ثبت‌نام کن و token هرکدام را در متغیر محلی جدا نگه دار. با token A یک Task خصوصی بساز و شناسه‌اش را ثبت کن.'],['مسیرهای خصوصی را امتحان کن','خواندن، update، delete و تغییر status همان شناسه را با token B اجرا کن؛ سپس بدون token و با token خراب هم امتحان کن.'],['عدم تغییر داده را اثبات کن','پس از هر تلاش B، با token A داده را بخوان. عنوان، وضعیت و وجود Task باید مطابق حالت قبل باشند؛ 403 یا 404 را مطابق قرارداد ثابت نگه دار.']],refs:[gin,sql],task:'collection آزمون مالکیت برای تمام عملیات خصوصی تحویل بده.',input:'Task خصوصی A؛ token معتبر B؛ درخواست GET/PATCH/DELETE روی همان شناسه.',expected:'B پاسخ 403 یا 404 مستند بگیرد؛ A هنوز همان Task را ببیند و داده تغییر نکرده باشد.',hint:'در query تغییر، owner_id را همراه id شرط کن و تعداد ردیف تغییرکرده را بررسی کن.',pitfall:'آزمون فقط GET کافی نیست؛ گاهی خواندن محافظت دارد ولی UPDATE یا DELETE بدون شرط مالک اجرا می‌شود.'},
 {intro:['ساختار پروژه باید جریان تصمیم‌ها را روشن کند. handler درخواست را می‌خواند، لایه منطق قانون را اجرا می‌کند و repository داده را ذخیره می‌کند؛ نام پوشه‌ها به‌تنهایی این مرزها را ایجاد نمی‌کند.','برای مرور ساختار، یک درخواست نامعتبر را انتخاب کن. دنبال‌کردن همین مسیر نشان می‌دهد validation کجاست، کدام بخش خطا را می‌شناسد و چه جایی status پاسخ انتخاب می‌شود.'],steps:[['ورودی نامعتبر بساز','POST /tasks را با عنوان خالی بفرست و status/body را ذخیره کن. خط اجرای درخواست را با debugger یا log محلی بدون اطلاعات حساس دنبال کن.'],['مسئولیت فایل‌ها را رسم کن','برای routing، binding، validation، service، repository و error mapping مسیر واقعی فایل و نام تابع را بنویس؛ بخشی را که واقعاً وجود ندارد به نمودار اضافه نکن.'],['یک تصمیم را توضیح بده','مثلاً بنویس چرا validation عنوان پیش از فراخوانی DB است. یک جایگزین ساده و هزینه تصمیم فعلی را هم ثبت کن.']],refs:[gin,goTest],task:'نمودار جریان درخواست عنوان خالی و یادداشت تصمیم بنویس.',input:'POST /tasks با {"title":""}.',expected:'خطای validation بدون INSERT در DB بازگردد و سند به تابع‌های موجود اشاره کند.',hint:'در تست می‌توانی تعداد رکوردها را پیش و پس درخواست مقایسه کنی.',pitfall:'ساختن لایه‌های متعدد بدون مسئولیت مشخص، دنبال‌کردن خطا را سخت‌تر می‌کند.'},
 {intro:['Regression یعنی رفتاری که قبلاً درست بوده دوباره خراب شود. تست نگهبان باید همان رفتار بیرونی را ثبت کند تا تغییر بعدی نیز شکست آن را آشکار کند.','یک تست که قبل از اصلاح هم پاس می‌شود، بازتولید bug نیست. ترتیب این جلسه ثبت ورودی شکست، مشاهده تست قرمز، اصلاح کوچک و اجرای مجدد است.'],steps:[['یک خطای مشخص انتخاب کن','مثلاً درخواست update با شناسه ناموجود به‌اشتباه 200 می‌دهد. status مطلوب، body و نبود تغییر داده را قبل از کد تعریف کن.'],['تست شکست‌خورده بساز','با DB تمرینی یا boundary مناسب همان درخواست را بفرست. نتیجه فعلی باید assertion را بشکند؛ اگر پاس شد، ورودی یا انتظار تست را بررسی کن.'],['اصلاح کوچک انجام بده','در محل مسئول نتیجه rows affected یا خطای not found را بررسی کن. تست نگهبان و سپس مجموعه تست مرتبط را اجرا و علت bug را کنار commit توضیح بده.']],refs:[goTest],task:'یک گزارش red→green قابل بازتولید ثبت کن.',input:'PATCH /tasks/999 برای کاربر معتبر، وقتی 999 وجود ندارد.',expected:'تست پیش از اصلاح شکست بخورد؛ بعد از اصلاح status not found و نبود تغییر DB اثبات شود.',hint:'از تست‌کردن تعداد فراخوانی یک تابع داخلی به‌عنوان تنها شاهد خودداری کن؛ نتیجه API و داده مهم‌اند.',pitfall:'عوض‌کردن انتظار تست به رفتار خراب برنامه، اصلاح bug نیست.'},
 {intro:['Race وقتی رخ می‌دهد که چند goroutine بدون هماهنگی به داده مشترک دسترسی دارند و دست‌کم یکی می‌نویسد. Deadlock وضعیت توقف انتظارهاست؛ race detector همه deadlockها را تشخیص نمی‌دهد.','هم‌زمانی و کیفیت مدل دو نوع شاهد متفاوت می‌خواهند. سالم‌بودن worker با تست و race detector سنجیده می‌شود؛ نتیجه آموزش با train/validation و تنظیمات آزمایش گزارش می‌شود.'],steps:[['مشکل کوچک بازتولید کن','یک شمارنده مشترک را از دو goroutine بدون محافظ افزایش بده و go test -race را اجرا کن. مثال را از داده واقعی سرویس جدا نگه دار.'],['هماهنگی روشن کن','یکی از روش‌های Mutex یا مالکیت داده از طریق Channel را انتخاب کن. مسیر پایان workerها و بستن channel را رسم کن؛ فقط یک صاحب مسئول close باشد.'],['گزارش‌ها را جدا بنویس','نتیجه -race و تست شمارنده را ثبت کن. برای Notebook همین هفته نیز loss و سنجه validation واقعی را بنویس و بهبود هر epoch را تضمین نکن.']],refs:[goTest,torch],task:'شمارنده ۱۰۰۰افزایش را بدون race و با خروج تمیز اجرا کن.',input:'دو worker که هرکدام ۵۰۰ بار افزایش انجام می‌دهند.',expected:'عدد نهایی ۱۰۰۰، پایان همه workerها و نبود گزارش race در تست اجراشده.',hint:'نبود خطا در یک اجرای ساده جای اجرای -race را نمی‌گیرد.',pitfall:'close کردن channel از چند worker ممکن است panic ایجاد کند؛ مالک پایان جریان را مشخص کن.'},
 {intro:['تحویل سرویس شامل کد، محیط و دستورهای قابل تکرار است. Compose تنها وقتی ارزش دارد که API واقعاً DB را پیدا کند، داده پایدار باشد و نبود متغیر ضروری خطای روشن بدهد.','Notebook نیز باید از ابتدا اجرا شود. اجرای انتخابی سلول‌ها ممکن است به متغیرهای باقی‌مانده در حافظه تکیه کند و نتیجه‌ای بسازد که در محیط تازه تکرار نمی‌شود.'],steps:[['از clone تازه شروع کن','پروژه را در مسیر تازه clone و .env.example را با مقادیر تمرینی کپی کن. دستورهای Compose و migration را دقیق به‌ترتیب README اجرا کن.'],['تست و پایداری را بررسی کن','go test ./... و مجموعه درخواست دو کاربر را اجرا کن. Task بساز، سرویس را restart کن و دوباره همان داده را بخوان؛ volume واقعی را حذف نکن.'],['آزمایش AI را بازاجرا کن','Kernel Notebook را restart کن و Run All بزن. دستگاه، نسخه بسته‌ها، تنظیمات، سنجه و محدودیت را در خروجی ثبت کن.']],refs:[docker,goTest,torch],task:'گزارش اجرای تمیز API و MNIST را کنار release ثبت کن.',input:'clone تازه، تنظیمات نمونه، DB بدون schema و Notebook بدون state قبلی.',expected:'راه‌اندازی طبق README پیش برود؛ تست‌ها و inference نمونه نتیجه واقعی بدهند یا محدودیت اجرا صریح ثبت شود.',hint:'زمان نصب یا دانلود dataset را از زمان آموزش مدل جدا بنویس.',pitfall:'CI سبز به‌تنهایی ثابت نمی‌کند volume یا دستور migration محیط محلی درست است.'},
 {intro:['طراحی پنل از جریان کار شروع می‌شود: ورود، دیدن فهرست و تغییر یک Task. هر تماس شبکه حالت انتظار و شکست دارد؛ اگر فقط صفحه موفقیت را رسم کنی، بخش بزرگی از رفتار محصول تعریف نشده می‌ماند.','Component باید مسئولیت قابل توضیح داشته باشد. فرم ورودی، فهرست و پیام خطا می‌توانند جدا باشند، اما state مشترک باید صاحب مشخصی داشته باشد.'],steps:[['جریان را رسم کن','مسیر ورود موفق، رمز نادرست، فهرست خالی، فهرست دارای Task و ویرایش Task را روی کاغذ یا فایل ساده رسم کن. دکمه برگشت و خروج را هم مشخص کن.'],['حالت API را اضافه کن','برای بارگیری فهرست، وضعیت loading، خطای شبکه، 401 و empty را با متن مشخص بنویس. دوباره‌فرستادن فرم نباید Task تکراری ناخواسته بسازد.'],['اجزا و state را تعیین کن','LoginForm، TaskList و TaskForm را فهرست کن. بنویس title فعلی، فهرست Task و وضعیت درخواست کجا ذخیره می‌شوند و چطور منتقل می‌شوند.']],refs:[react],task:'طرح سه صفحه و جدول stateهای شبکه بساز.',input:'کاربر تازه بدون Task؛ درخواست فهرست کند؛ درخواست ناموفق 401.',expected:'برای هر حالت، پیام و اقدام بعدی کاربر معلوم باشد و طرح به صفحه خالی بدون توضیح ختم نشود.',hint:'برای هر دکمه بنویس «پس از کلیک، کدام داده تغییر می‌کند؟».',pitfall:'ساخت Component بر اساس رنگ یا اندازه، مسئولیت و جریان داده را روشن نمی‌کند.'},
 {intro:['TypeScript پیش از اجرا ناسازگاری نوع‌های کد را می‌گیرد. پاسخ شبکه در زمان اجرا می‌آید و تایپ‌کردن آن به شکل Task تضمین نمی‌کند که سرور واقعاً title یا id معتبر فرستاده است.','این مرور باید دو خطا را جدا نشان بدهد: خطایی که tsc می‌گیرد و داده‌ای که از نظر syntax معتبر است اما ساختار مطلوب برنامه را ندارد.'],steps:[['سه خطای نوع عمدی بساز','به id عددی رشته بده، status خارج از Union بنویس و property ناموجود را بخوان. tsc را اجرا و پیام هر خطا را به زبان خودت توضیح بده.'],['مرز JSON را بررسی کن','پاسخ آزمایشی {"id":1} را به‌جای Task کامل دریافت کن. با unknown و بررسی فیلدها یا schema معتبرسازی کن و پیام داده نامعتبر بده.'],['اصلاح را ثبت کن','خطاهای عمدی را اصلاح کن تا Build سبز شود؛ مثال JSON خراب را در تست نگه دار. توضیح تفاوت compile-time و runtime را کنار نمونه‌ها بنویس.']],refs:[ts],task:'یک تابع parseTask برای مرز پاسخ API آزمایش کن.',input:'{"id":1,"title":"Go","status":"todo"} و {"id":"bad"}.',expected:'داده نخست پذیرفته و داده دوم با خطای کنترل‌شده رد شود؛ کد نهایی TypeScript کامپایل شود.',hint:'as Task اعتبارسنجی انجام نمی‌دهد؛ پیش از ساخت Task به داده unknown نگاه کن.',pitfall:'خاموش‌کردن خطا با any، مسئله داده نامعتبر را حل نمی‌کند.'},
 {intro:['رابط قابل استفاده باید با داده و روش تعامل متفاوت درست بماند. یک فهرست پنج‌تایی با ماوس، شواهد کافی برای فرم یا فهرست بلند نیست.','بازبینی Component در این مرحله یعنی بررسی مسئولیت و حفظ state؛ اگر با جابه‌جایی یا حذف یک Task ورودی Task دیگری عوض شود، کلیدها و مالک state را بررسی کن.'],steps:[['سه وضعیت داده بساز','فهرست خالی، فهرست ۱۰۰ Task با عنوان‌های بلند و پاسخ خطای شبکه را در محیط آزمایشی نمایش بده. پیام و اقدام هر حالت را یادداشت کن.'],['با کیبورد عبور کن','از ابتدای صفحه Tab بزن؛ ترتیب فوکوس، labelها، دکمه submit و پیام خطا را بررسی کن. فقط با کیبورد یک Task اضافه و ویرایش کن.'],['اجزا را اصلاح کن','کلید پایدار فهرست، state فرم و محل نمایش خطا را بازبینی کن. یک مشکل واقعی را اصلاح و پیش/پس آن را با سناریو توضیح بده.']],refs:[react],task:'گزارش بازبینی UI با سه مشکل و نتیجه اصلاح تهیه کن.',input:'۱۰۰ Task، عنوان ۲۰۰کاراکتری، فرم عنوان خالی و درخواست کند.',expected:'صفحه قابل پیمایش، focus قابل دیدن و خطاها متنی باشند؛ داده خالی با وضعیت loading اشتباه نشود.',hint:'برای بازآزمایی، سناریو را با نام دکمه‌ها و ورودی دقیق بنویس.',pitfall:'رنگ قرمز بدون متن، علت خطای فرم را برای همه کاربران منتقل نمی‌کند.'},
 {intro:['تحویل Full-stack یعنی تغییر UI به درخواست API و سپس تغییر پایدار DB برسد. اگر فقط state محلی تغییر کند، با refresh حقیقت سرور آشکار می‌شود.','کنترل مجوز باید در Backend بماند؛ UI می‌تواند گزینه‌های نامناسب را پنهان کند، ولی هر درخواست مستقیم همچنان باید بررسی مالکیت شود.'],steps:[['چهار جزء را اجرا کن','PostgreSQL، Go/Gin و React را طبق README بالا بیاور. baseURL، تنظیمات توسعه و CORS لازم محیط خودت را مستند کن.'],['گردش واقعی بساز','با A وارد شو، Task بساز، عنوان و status را عوض کن و refresh بزن. همان رکورد را از API و DB مشاهده کن تا تغییر واقعی اثبات شود.'],['کاربر B را جدا آزمایش کن','با نشست جدا یا خروج و ورود B، فهرست و درخواست مستقیم شناسه Task A را امتحان کن. read/update/delete باید در سرور رد شوند.']],refs:[react,gin],task:'سناریوی دو کاربر را از UI تا DB اجرا و ضبط کن.',input:'A یک Task به نام shot01 می‌سازد؛ B شناسه همان Task را در درخواست مستقیم استفاده می‌کند.',expected:'تغییر A پس از refresh بماند؛ B نتواند داده خصوصی A را بخواند یا تغییر دهد.',hint:'برای تفکیک خطای UI و سرور، همان درخواست را در ابزار تست API هم تکرار کن.',pitfall:'دیدن Task فقط در مرورگر سازنده، شاهد ذخیره‌شدن در PostgreSQL نیست.'},
 {intro:['انتخاب مدل با مسئله شروع می‌شود: چه ورودی‌ای می‌گیرد و چه خروجی‌ای لازم داری؟ مدل بزرگ‌تر الزاماً برای تمرین آموزشی بهتر نیست و ممکن است حتی مرحله بارگذاری از حافظه دستگاه بیشتر بخواهد.','شناسنامه مدل باید نسخه، مجوز و محدودیت را ثبت کند. نیاز حافظه به وزن‌ها محدود نیست؛ طول ورودی، activation، batch و optimizer هم اثر دارند.'],steps:[['هدف کوچک تعریف کن','برای نمونه یک طبقه‌بندی متن کوتاه یا بازنویسی محدود انتخاب کن. نوع داده، زبان و سنجه موفقیت را پیش از انتخاب مدل بنویس.'],['Model card را بررسی کن','مدل و dataset کوچک انتخاب کن؛ نام دقیق، revision، مجوز، محدودیت کاربرد و قالب ورودی/خروجی را از صفحه رسمی خودشان ثبت کن.'],['اجرای پایه را امتحان کن','چند نمونه را با batch کوچک روی CPU یا دستگاه واقعی اجرا کن. RAM/VRAM و زمان را اندازه بگیر؛ مسیر Colab را فقط اگر واقعاً آماده کرده‌ای اجراشده معرفی کن.']],refs:[hf],task:'یک شناسنامه انتخاب مدل با نتیجه اجرای پایه تهیه کن.',input:'سه متن کوتاه ساختگی با زبان و طول مشخص؛ دستگاه واقعی در دسترس.',expected:'نام مدل، مجوز، revision، تنظیمات و خروجی واقعی نمونه‌ها همراه محدودیت حافظه ثبت شوند.',hint:'اگر مدل جا نشد ابتدا اندازه مدل و طول توالی را کاهش بده؛ نام GPU فرضی رودمپ را مشخصات سیستم خودت ننویس.',pitfall:'قابل دانلود بودن وزن‌ها به معنی مجازبودن همه کاربردهای تجاری یا داده‌ها نیست.'},
 {intro:['طرح آزمایش پیش از اجرا، مقایسه را قابل تفسیر می‌کند. اگر داده، seed، معیار یا تنظیمات در میانه عوض شوند، تفاوت نتیجه را نمی‌توان به یک عامل نسبت داد.','Checkpoint فقط فایل وزن نیست؛ برای بازتولید باید مدل پایه، tokenizer، تنظیمات، نسخه بسته‌ها و روش آماده‌سازی داده را هم بشناسی.'],steps:[['داده و معیار را ثابت کن','شناسه یا فایل نمونه‌های train/validation/test را جدا ثبت کن. یک معیار مناسب مسئله و baseline بدون آموزش تعریف کن؛ test را برای تصمیم‌های میانی استفاده نکن.'],['بودجه را بنویس','Epoch، batch size، learning rate، طول توالی و روش full/LoRA را با ظرفیت دستگاه واقعی انتخاب کن. ابتدا اجرای کوتاه چند batch را برنامه‌ریزی کن.'],['توقف و ذخیره را تعریف کن','نام checkpointها، فاصله ارزیابی و شرط توقف را مشخص کن. فایل تنظیمات و seed را کنار گزارش نگه دار و اندازه حافظه را ثبت کن.']],refs:[hf,torch],task:'فایل طرح آزمایش و baseline پیش از آموزش بساز.',input:'dataset کوچک با تقسیم ثابت؛ حداکثر زمان اجرا و حافظه قابل استفاده خودت.',expected:'یک نفر بتواند از روی طرح بفهمد چه داده، مدل، سنجه و تنظیماتی باید اجرا شوند.',hint:'حداقل دو تنظیم را هم‌زمان تغییر نده؛ ابتدا baseline ثابت را اجرا کن.',pitfall:'استفاده مکرر از test برای انتخاب بهترین epoch، ارزیابی نهایی را خوش‌بینانه می‌کند.'},
 {intro:['Loss آموزش و کیفیت روی داده تازه دو چیز متفاوت‌اند. اگر train بهتر و validation بدتر می‌شود، ادامه آموزش ممکن است حفظ‌کردن داده یا Overfitting را بیشتر کند.','گزارش میان‌مرحله باید مشاهده را از تفسیر جدا کند. «validation loss افزایش یافت» مشاهده است؛ «learning rate زیاد است» فرضیه‌ای است که به آزمایش بعدی نیاز دارد.'],steps:[['گزارش epochها را کنار هم بگذار','برای هر epoch، train loss، validation loss یا سنجه مناسب، زمان و تنظیمات را در جدول بنویس. نمونه‌هایی که مدل اشتباه می‌کند را بدون انتخاب گزینشی ثبت کن.'],['تصمیم را با معیار بگیر','نتیجه را با baseline و شرط توقف طرح قبلی مقایسه کن. اگر validation بدتر شده، checkpoint مناسب را نگه دار و ادامه را صرفاً به دلیل کاهش train توجیه نکن.'],['یک عامل بعدی انتخاب کن','برای بهبود احتمالی تنها یکی از داده، learning rate، تعداد epoch یا regularization را بررسی کن. فرضیه و معیار تأییدش را پیش از اجرای تازه بنویس.']],refs:[hf,torch],task:'یک تصمیم ادامه یا توقف با جدول شواهد ثبت کن.',input:'train loss: ۰٫۸، ۰٫۵، ۰٫۳؛ validation loss: ۰٫۹، ۰٫۷، ۱٫۰.',expected:'epoch سوم به‌صرف train کمتر بهترین اعلام نشود؛ انتخاب checkpoint و محدودیت نتیجه توضیح داده شود.',hint:'برای تفسیر عددها، یکسان‌بودن مجموعه validation و روش محاسبه را هم بررسی کن.',pitfall:'یک نمودار زیبا بدون تعداد نمونه و تنظیمات، نتیجه قابل تکرار نیست.'},
 {intro:['تحویل ماه پنجم دو خروجی متفاوت دارد: نتیجه Fine-tuning و اندازه‌گیری CPU/GPU. اولی کیفیت مدل را می‌سنجد و دومی رفتار اجرا روی سخت‌افزار مشخص را.','اگر GPU در دسترس نیست، جدول CPU واقعی و وضعیت «GPU اجرا نشده» خروجی معتبرتری از تخمین ارائه‌شده به‌عنوان اندازه‌گیری است. شکست آزمایش هم باید قابل توضیح باشد.'],steps:[['گزارش مدل را تکمیل کن','مدل پایه، مجوز داده، تقسیم‌ها، تنظیمات، معیار baseline و پس از آموزش و نمونه شکست را در README یا گزارش مستقل جمع کن.'],['مقایسه سخت‌افزار را ثبت کن','برای deviceهای واقعاً اجراشده، نسخه بسته، dtype، batch، warm-up، تعداد تکرار، زمان میانه و حافظه را بنویس. زمان انتقال را با زمان محاسبه قاطی نکن.'],['دستور بازتولید را امتحان کن','از محیط تازه یک inference و یک اجرای کوچک سنجش زمان انجام بده. فایل‌های حجیم و داده حساس را بی‌بررسی داخل Git نگذار؛ محل دریافت مجازشان را توضیح بده.']],refs:[hf,torch],task:'گزارش نهایی با فرمان اجرای کوچک و جدول دستگاه‌ها بساز.',input:'یک checkpoint واقعی، داده test نگه‌داشته‌شده و نتایج چند تکرار زمان‌سنجی.',expected:'خواننده بداند چه چیزی واقعاً اجرا شده، نتیجه کیفیت چیست و کدام بخش به‌علت محدودیت اجرا نشده است.',hint:'«بهتر» را به عدد و سنجه متصل کن؛ اگر بهبود ندیدی همان را گزارش کن.',pitfall:'مقایسه FP32 روی CPU با FP16 روی GPU بدون ذکر dtype، نتیجه را گمراه‌کننده می‌کند.'},
 {intro:['پذیرش StudioFlow از داستان کاربر به رفتار قابل بررسی تبدیل می‌شود. «مدیریت Shot» خیلی بزرگ است؛ «مدیر بتواند Shot را در Sequence پروژه خودش بسازد» ورودی و مرز مجوز دارد.','تصمیم معماری باید مسئله، انتخاب و پیامد را ثبت کند. Redis یا سرویس جدا وقتی معنا دارند که کاربرد و رفتار هنگام خرابی‌شان معلوم باشد.'],steps:[['دامنه را کوچک کن','فهرست Project، Sequence، Shot، Task، عضو و Role، وضعیت، نسخه فایل، Deadline و داشبورد را بنویس. قابلیت AI نسخه اول را فقط خلاصه‌سازی Shot نگه دار.'],['Issue قابل پذیرش بساز','برای هر خروجی، actor، پیش‌شرط، ورودی، خروجی مطلوب و آزمون ممنوع را بنویس. issue بزرگ را به کارهای Backend، UI و تست خرد کن.'],['یک تصمیم معماری ثبت کن','مرز Go API، PostgreSQL، React و سرویس Python را رسم کن. برای Redis کاربرد محدود و رفتار نبودنش را توضیح بده؛ یک جایگزین و هزینه انتخاب فعلی را بنویس.']],refs:[issue,gin],task:'برای ساخت Shot و خلاصه‌سازی آن دو issue مستقل آماده کن.',input:'مدیر پروژه A، کاربر خارج A، Sequence متعلق به A و توضیح Shot ساختگی.',expected:'معیار مجوز، رابطه Shot/Sequence و شکست سرویس AI در issueها وجود داشته باشد.',hint:'قابلیت AI را از مسیر اصلی ایجاد/ویرایش Shot جدا کن تا خرابی آن تولید را متوقف نکند.',pitfall:'نوشتن نام ده ابزار در نمودار، جای تعریف مسئولیت و قرارداد بین سرویس‌ها را نمی‌گیرد.'},
 {intro:['دموی گردش کار باید یک مسیر واقعی تولید را نشان بدهد: پروژه، Sequence و Shot ساخته می‌شوند، کار به عضو واگذار می‌شود، وضعیت تغییر می‌کند و نسخه فایل و Deadline باقی می‌مانند.','دو نقش متفاوت باید واقعاً اختیار متفاوت داشته باشند. با عوض‌کردن کاربر تنها ظاهر UI را نبین؛ درخواست مستقیم ممنوع را هم امتحان کن و تاریخچه نسخه را بعد از refresh بررسی کن.'],steps:[['داده ساختگی سناریو را بساز','یک پروژه، یک Sequence و دو Shot با نام‌های مشخص ایجاد کن. یک مدیر و یک عضو وارد تیم کن و Task را به عضو واگذار کن.'],['گردش تحویل را اجرا کن','عضو وضعیت Task/Shot را تغییر دهد و نسخه دوم فایل را ثبت کند. مدیر Deadline را تغییر دهد؛ dashboard باید از رکوردهای واقعی شمارش تازه نشان دهد.'],['مرزها و خطا را ثبت کن','با کاربر خارج پروژه read/update را امتحان کن. سرویس AI را در محیط تست قطع کن و نشان بده مدیریت Shot همچنان کار می‌کند؛ خطاهای پیدا‌شده را با مراحل تکرار بنویس.']],refs:[react,gin],task:'دموی کوتاه Shot از ایجاد تا نسخه دوم تحویل ضبط کن.',input:'دو Shot با یکی done؛ فایل v1 و v2؛ کاربر عضو و کاربر خارج پروژه.',expected:'تعداد واقعی Shotها، حفظ v1، Deadline پس از refresh و رد دسترسی خارجی دیده شوند.',hint:'دمو را با داده کم اما سناریوی کامل بساز؛ ده صفحه خالی شواهد بیشتری نمی‌دهند.',pitfall:'بازنویسی نام فایل قبلی به‌عنوان نسخه جدید، تاریخچه قابل بررسی ایجاد نمی‌کند.'},
 {intro:['مستند API باید برای مصرف‌کننده قابل اجرا باشد: URL، روش احراز هویت، body، پاسخ، status خطا و نمونه مسیر کامل لازم‌اند. فقط فهرست endpointها برای ساخت Client کافی نیست.','سند معماری باید با کد نهایی منطبق باشد. تصمیم‌های رهاشده را در نمودار اصلی نگه ندار؛ محدودیت واقعی و دلیل انتخاب نسخه فعلی را توضیح بده.'],steps:[['قرارداد endpointها را کامل کن','برای login، ایجاد Project/Sequence/Shot، تغییر status، نسخه فایل و خلاصه‌سازی، ورودی و پاسخ موفق و خطا را مستند کن. token و داده نمونه جعلی باشند.'],['روابط و مجوز را روشن کن','schema و نقش‌ها را با جدول دسترسی بنویس. مشخص کن مالکیت از کدام رابطه پروژه بررسی می‌شود و خطای مجوز چه status می‌دهد.'],['راهنما را با اجرا بسنج','فقط از روی مستندات با ابزار API وارد شو و یک Shot بساز. هر قدم مبهم یا فیلد جاافتاده را اصلاح و تصمیم‌های معماری را به فایل‌های واقعی لینک کن.']],refs:[api,gin],task:'یک راهنمای قابل اجرا از ورود تا ایجاد Shot تحویل بده.',input:'کاربر مدیر آزمایشی، Project و Sequence نمونه و body ساختگی Shot.',expected:'مصرف‌کننده بدون خواندن source بتواند مسیر سالم و یک درخواست غیرمجاز را تکرار کند.',hint:'برای هر نمونه موفق حداقل یک نمونه خطای مرتبط بنویس.',pitfall:'کپی token واقعی در مثال مستندات، اطلاعات دسترسی را عمومی می‌کند.'},
 {intro:['پورتفولیو یک ادعای قابل بررسی است. شخص بررسی‌کننده باید مسئله، سهم تو، راه اجرا، تست، نتیجه و محدودیت را سریع پیدا کند؛ پروژه ناقص را کامل معرفی نکن.','در پایان ماه ششم هدف اصلی هنوز Backend با Go است. آشنایی با مدل و GPU را با نمونه آزمایش بنویس، نه عنوان تخصصی‌ای که شواهد مستقل برایش نداری.'],steps:[['بسته تحویل را مرتب کن','README انگلیسی، API docs، نمودار معماری، Compose، نتیجه تست‌ها و لینک دمو واقعی را کنار هم قرار بده. secret، dump واقعی و داده خصوصی را از بسته عمومی خارج کن.'],['دموی کامل ضبط کن','ایجاد Project تا Shot و Task، تغییر status، نسخه فایل، Deadline و خلاصه‌سازی یا خطای کنترل‌شده AI را در چند دقیقه نشان بده. سناریو با دو نقش را فراموش نکن.'],['شاهد و شکاف را جدا بنویس','برای Go، SQL، Docker، React و AI به فایل یا دمو شاهد بده. ضعف‌ها و مسیر ادامه Backend، AI Application، ML یا GPU را با اولویت واقع‌بینانه ثبت کن.']],refs:[issue,docker],task:'صفحه معرفی StudioFlow و گزارش آمادگی شغلی بساز.',input:'مخزن، دمو واقعی، نتیجه تست و سه تصمیم فنی پروژه خودت.',expected:'هر ادعای فنی قابل مشاهده باشد؛ محدودیت‌ها و بخش‌های اجرا‌نشده صریح بمانند.',hint:'اولین بند README را به مسئله و کاربر پروژه اختصاص بده؛ نصب و جزئیات فنی بعد از آن بیایند.',pitfall:'نوشتن همه فناوری‌های آشنا در رزومه بدون نمونه قابل توضیح، دفاع از رزومه را دشوار می‌کند.'},
 {intro:['بازبینی تحویل یعنی هر تیک به یک شاهد وصل شود. وجود فایل Compose ثابت نمی‌کند برنامه با آن بالا می‌آید؛ وجود لینک دمو هم تضمین نمی‌کند سناریوی اصلی سالم باشد.','برای رفع نقص، ریسک رفتار را مقدم کن: نشت داده و از دست‌رفتن داده از اصلاح ظاهری مهم‌ترند. هر نقص باید ورودی و رفتار مطلوب مشخص داشته باشد.'],steps:[['تیک‌ها را ممیزی کن','برای هر چک‌لیست پروژه، فایل، فرمان تست، خروجی یا لینک شاهد را ثبت کن. موارد بدون شاهد را به وضعیت ناقص برگردان و علت را یادداشت کن.'],['سه نقص را اولویت بده','یک نقص مجوز، یک نقص پایداری/اجرا و یک نقص مستندات یا کیفیت خروجی را انتخاب کن. مراحل تکرار و معیار بسته‌شدن را بنویس.'],['از بیرون مسیر را تکرار کن','مخزن و دمو و لینک‌های مستندات را با یک نشست تازه باز کن؛ تست دو کاربر و restart را روی داده آزمایشی تکرار کن. وضعیت واقعی هر مورد را ثبت کن.']],refs:[issue,goTest,docker],task:'جدول ممیزی پروژه‌ها با شاهد و سه نقص اولویت‌دار بساز.',input:'چک‌لیست فعلی و لینک مخزن/دمو/مستندات هر پروژه.',expected:'هیچ مورد بی‌شاهد کامل علامت نخورد؛ هر نقص owner، ورودی و معیار پذیرش داشته باشد.',hint:'اگر محیط اجرای بخشی موجود نیست، آن را «بررسی نشد» بنویس؛ حدس را نتیجه تست معرفی نکن.',pitfall:'حفظ تیک فقط برای زیباترشدن درصد، برنامه مرور بعدی را از واقعیت دور می‌کند.'},
 {intro:['رزومه باید انتخاب‌شده و قابل دفاع باشد. برای موقعیت Junior Backend، Go، HTTP، SQL، مجوز، تست و Docker را با تجربه پروژه‌ای واقعی توضیح بده.','آگهی شغلی فهرست اقدام بعدی است. لازم نیست پیش از درخواست همه واژه‌ها را بلد باشی، اما باید تفاوت مهارت مستقل، مهارت با راهنما و موضوع آشنایی را صادقانه مشخص کنی.'],steps:[['شواهد را جمع کن','برای هر ادعای رزومه یک پروژه، فایل تست، گزارش یا دمو معرفی کن. یک نمونه اصلاح خطا و یک تصمیم معماری با tradeoff آماده کن.'],['سه آگهی را مقایسه کن','سه آگهی مرتبط و واقعی انتخاب کن؛ مهارت‌های تکرارشونده و شواهد خودت را در جدول بنویس. داده شخصی یا درخواست شغل را بدون تصمیم خودت ارسال نکن.'],['برنامه بعدی بساز','دو شکاف مهم را به تمرین کوچک هفته بعد تبدیل کن. رزومه و README را با عنوان Junior Backend و نتایج واقعی نهایی کن و پاسخ پنج‌دقیقه‌ای معرفی پروژه را تمرین کن.']],refs:[issue],task:'جدول تطبیق سه آگهی و دو تمرین بعدی تهیه کن.',input:'سه آگهی با محور Backend و فهرست شاهدهای خودت.',expected:'هر مهارت با شاهد یا شکاف مشخص علامت بخورد؛ خروجی درس تضمین استخدام معرفی نشود.',hint:'برای هر ضعف، فعل قابل سنجش بنویس؛ مثلاً «یک transaction با rollback تست کنم» از «SQL بیشتر بخوانم» روشن‌تر است.',pitfall:'اضافه‌کردن عنوان ML/GPU Engineer با چند تمرین مقدماتی، محدوده تجربه را نادرست نشان می‌دهد.'},
];

